const specialty = $input.item.json.specialty || 'neuro';
let domains = [];

if (specialty === 'physio') {
  domains = ["ncbi.nlm.nih.gov", "pubmed.ncbi.nlm.nih.gov", "nature.com", "thelancet.com", "sciencedirect.com"];
} else if (specialty === 'psych') {
  domains = ["ncbi.nlm.nih.gov", "pubmed.ncbi.nlm.nih.gov", "nature.com", "apa.org", "sciencedirect.com"];
} else {
  // Default to neuro
  domains = ["ncbi.nlm.nih.gov", "pubmed.ncbi.nlm.nih.gov", "nature.com", "cell.com", "sciencedirect.com"];
}

return {
  query: $input.item.json.query,
  includeDomains: domains
};

try {
  const results = $input.item.json.results || [];
  if (results.length === 0) {
    return { response: "No relevant results found for this query." };
  }

  let parsedString = "";
  results.forEach((r, index) => {
    parsedString += `[Result ${index + 1}]\nTitle: ${r.title}\nURL: ${r.url}\n`;

    // NEW LOGIC: Prefer clean Semantic Highlights over raw website text
    if (r.highlights && r.highlights.length > 0) {
      parsedString += `Highlights:\n${r.highlights.join("\\n...\\n")}\n`;
    } else if (r.text) {
      // Fallback for sites where highlights failed
      parsedString += `Content: ${r.text.substring(0, 800)}...\n`;
    }
    parsedString += "\n";
  });

  return { response: parsedString };
} catch (error) {
  return { response: "SYSTEM MESSAGE: The Exa search tool encountered an error processing results." };
}
